    #[local] Notation ent := (Z * (Z * Z))%type.

    Definition hda (l : list ent) (t : Z) : Z := match l with [] => t | b :: _ => fst b end.
    Fixpoint lnk (M : mem) (Ls : list ent) (t : Z) : Prop :=
      match Ls with
      | [] => True
      | a :: Ls' => cell8 SEGS M (fst a) (hda Ls' t) /\ lnk M Ls' t
      end.
